// T-009: validates the 3 static AgentDojo-derived corpus files
// (crates/ferrite-eval/tests/agentdojo_corpus/*.json) generated by
// `ferrite_eval::agentdojo::adapt_agentdojo_slack_task` against real
// AgentDojo Slack-suite injection tasks (see that module's doc comment for
// citation and the tool-substitution mapping). All three must load through
// the same public `corpus::load_case`/`load_corpus` every hand-authored case
// goes through, and must be tagged `Tier::Tier3AgentDojo`/`Author::AgentDojo`.

use std::path::PathBuf;

use ferrite_eval::corpus::{load_case, load_corpus};
use ferrite_ipi::dataset::{Author, Tier};

fn corpus_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("agentdojo_corpus")
}

#[test]
fn agentdojo_corpus_three_files_present() {
    let dir = corpus_dir();
    let count = std::fs::read_dir(&dir)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", dir.display()))
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.extension().and_then(|x| x.to_str()) == Some("json"))
        .count();
    assert_eq!(count, 3, "expected 3 .json files in {}", dir.display());
}

#[test]
fn agentdojo_corpus_each_file_validates_as_tier3_agentdojo() {
    let dir = corpus_dir();
    let mut paths: Vec<PathBuf> = std::fs::read_dir(&dir)
        .unwrap()
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.extension().and_then(|x| x.to_str()) == Some("json"))
        .collect();
    paths.sort();

    let mut failures = Vec::new();
    for path in &paths {
        let name = path.file_name().unwrap().to_string_lossy();
        match load_case(path) {
            Ok((case, _content)) => {
                if case.tier != Tier::Tier3AgentDojo {
                    failures.push(format!(
                        "{name}: tier is {:?}, expected Tier3AgentDojo",
                        case.tier
                    ));
                }
                if case.author != Author::AgentDojo {
                    failures.push(format!(
                        "{name}: author is {:?}, expected AgentDojo",
                        case.author
                    ));
                }
                if case.taxonomy_anchor.is_none() {
                    failures.push(format!(
                        "{name}: taxonomy_anchor is None — every AgentDojo-derived case must cite its source task"
                    ));
                }
                println!("PASS  {name}  (case_id {})", case.case_id);
            }
            Err(e) => {
                println!("FAIL  {name}  -> {e}");
                failures.push(format!("{name}: {e}"));
            }
        }
    }

    assert!(
        failures.is_empty(),
        "\n{} failure(s):\n  {}",
        failures.len(),
        failures.join("\n  ")
    );
}

#[test]
fn agentdojo_corpus_batch_load() {
    let dir = corpus_dir();
    match load_corpus(&dir) {
        Ok(cases) => {
            assert_eq!(cases.len(), 3);
            assert!(cases
                .iter()
                .all(|(case, _)| case.tier == Tier::Tier3AgentDojo));
        }
        Err(errors) => {
            let joined = errors
                .iter()
                .map(|e| e.to_string())
                .collect::<Vec<_>>()
                .join("\n  ");
            panic!(
                "batch load reported {} error(s):\n  {}",
                errors.len(),
                joined
            );
        }
    }
}
